defmodule KVStore do
  use GenServer

  def start_link(_), do: GenServer.start_link(__MODULE__, %{}, name: __MODULE__)
  def get(key), do: GenServer.call(__MODULE__, {:get, key})
  def put(key, val), do: GenServer.cast(__MODULE__, {:put, key, val})

  @impl true
  def handle_call({:get, key}, _from, state), do: {:reply, Map.get(state, key), state}
  @impl true
  def handle_cast({:put, key, val}, state), do: {:noreply, Map.put(state, key, val)}
end

defmodule RateLimiter do
  use Agent
  def start_link, do: Agent.start_link(fn -> %{} end, name: __MODULE__)
  def check(ip) do
    Agent.get_and_update(__MODULE__, fn state ->
      count = Map.get(state, ip, 0)
      if count < 100, do: {:allow, Map.put(state, ip, count + 1)}, else: {:deny, state}
    end)
  end
end

defmodule Stack do
  defstruct elements: []
  def push(%Stack{elements: elms}, item), do: %Stack{elements: [item | elms]}
  def pop(%Stack{elements: [head | tail]}), do: {head, %Stack{elements: tail}}
  def pop(%Stack{elements: []}), do: {:empty, %Stack{}}
end
